<template><AppLayout><main class="mx-auto max-w-6xl space-y-6"><header class="rounded-2xl bg-gradient-to-br from-primary-600 to-primary-800 p-7 text-white"><p class="text-sm text-primary-100">发卡商城</p><h1 class="text-3xl font-bold">发卡商城</h1><p class="mt-3 text-sm text-primary-100">购买成功后立即交付兑换码；商城不验证外部兑换结果。</p></header><nav class="flex gap-6 border-b"><button class="border-b-2 pb-3" :class="tab==='products'?'border-primary-600 text-primary-600':'border-transparent text-gray-500'" @click="tab='products'">商品</button><button class="border-b-2 pb-3" :class="tab==='orders'?'border-primary-600 text-primary-600':'border-transparent text-gray-500'" @click="tab='orders'">我的订单</button></nav><section v-if="tab==='products'" class="grid gap-5 md:grid-cols-2 xl:grid-cols-3"><article v-for="p in products" :key="p.id" class="flex min-h-60 flex-col rounded-xl border bg-white p-6 dark:border-dark-700 dark:bg-dark-900"><div class="flex-1"><h2 class="text-lg font-semibold">{{p.name}}</h2><p class="mt-3 text-sm text-gray-500">{{p.description}}</p><p v-if="p.limit_per_user" class="mt-2 text-xs text-gray-500">每个账户限购 {{p.limit_per_user}} 次</p></div><div class="mt-5 flex justify-between border-t pt-4"><div><b class="text-xl text-primary-600">{{money(p.price)}}</b><p class="text-xs text-gray-500">{{p.available_stock?`剩余 ${p.available_stock} 件`:'已售罄'}}</p></div><button class="btn btn-primary" :disabled="!p.available_stock" @click="target=p">立即购买</button></div></article></section><section v-else><div class="card"><div class="border-b p-5"><h2 class="font-semibold">我的订单</h2><p class="mt-1 text-sm text-gray-500">已交付兑换码可随时在此查看。</p></div><DataTable :columns="columns" :data="orders" :loading="loading" row-key="id"><template #cell-price="{value}">{{money(value)}}</template><template #cell-code="{value}"><code class="font-mono text-xs">{{value}}</code></template><template #cell-created_at="{value}">{{time(value)}}</template><template #cell-actions="{row}"><button class="btn btn-secondary btn-sm" @click="copy(row.code)">复制兑换码</button></template></DataTable></div></section><BaseDialog :show="!!target" title="确认购买" @close="target=null"><template v-if="target"><p>{{target.name}}</p><p class="mt-3 text-lg font-semibold">{{money(target.price)}}</p><p class="mt-4 text-sm text-gray-500">支付成功后立即交付兑换码，商城不验证外部兑换结果。</p></template><template #footer><button class="btn btn-secondary" @click="target=null">取消</button><button class="btn btn-primary" :disabled="buying" @click="purchase">确认支付</button></template></BaseDialog><BaseDialog :show="!!delivered" title="兑换码已交付" @close="delivered=null"><code v-if="delivered" class="block break-all rounded bg-gray-50 p-4 font-mono">{{delivered.code}}</code><template #footer><button class="btn btn-secondary" @click="copy(delivered?.code||'')">复制</button><button class="btn btn-primary" @click="delivered=null;tab='orders'">查看订单</button></template></BaseDialog></main></AppLayout></template>
<script setup lang="ts">
import{onMounted,ref}from'vue';import AppLayout from '@/components/layout/AppLayout.vue';import BaseDialog from '@/components/common/BaseDialog.vue';import DataTable from '@/components/common/DataTable.vue';import type{Column}from '@/components/common/types';import{shopAPI,type ShopOrder,type ShopProduct}from '@/api/shop';import{useAppStore}from '@/stores/app';import{useAuthStore}from '@/stores/auth';import{formatDateTimeStandard}from '@/utils/format'
const app=useAppStore(),auth=useAuthStore(),products=ref<ShopProduct[]>([]),orders=ref<ShopOrder[]>([]),loading=ref(true),tab=ref<'products'|'orders'>('products'),target=ref<ShopProduct|null>(null),delivered=ref<ShopOrder|null>(null),buying=ref(false),columns:Column[]=[{key:'order_no',label:'订单号'},{key:'product_name',label:'商品'},{key:'price',label:'金额'},{key:'code',label:'兑换码'},{key:'created_at',label:'购买时间'},{key:'actions',label:'操作'}],money=(v:number)=>`¥${Number(v||0).toFixed(2)}`,time=(v:string|null|undefined)=>formatDateTimeStandard(v)||'-'
async function load(){loading.value=true;try{[products.value,orders.value]=await Promise.all([shopAPI.listProducts(),shopAPI.listOrders()])}finally{loading.value=false}}async function purchase(){if(!target.value)return;buying.value=true;try{const order=await shopAPI.purchase(target.value.id);await auth.refreshUser();orders.value.unshift(order);products.value=products.value.map(p=>p.id===target.value?.id?{...p,available_stock:p.available_stock-1}:p);target.value=null;delivered.value=order}catch{app.showError('购买失败，请检查余额、库存或限购次数')}finally{buying.value=false}}async function copy(v:string){try{await navigator.clipboard.writeText(v);app.showSuccess('兑换码已复制')}catch{app.showError('复制失败')}}onMounted(load)
</script>
